+        --shadow: 0 20px 60px rgba(0, 0, 0, 0.45);
+        --radius: 20px;
+      }
+
+      * {
+        box-sizing: border-box;
+      }
+
+      html {
+        scroll-behavior: smooth;
+      }
+
+      body {
+        margin: 0;
+        min-height: 100vh;
+        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
+          sans-serif;
+        background:
+          radial-gradient(circle at top, rgba(143, 180, 255, 0.2), transparent 36%),
+          linear-gradient(180deg, #090d1a 0%, var(--bg) 100%);
+        color: var(--text);
+      }
+
+      a {
+        color: inherit;
+      }
+
+      .skip-link {
+        position: absolute;
+        left: 1rem;
+        top: 1rem;
+        padding: 0.75rem 1rem;
+        border-radius: 999px;
+        background: var(--accent);
+        color: #08101f;
+        font-weight: 700;
+        text-decoration: none;
+        transform: translateY(-160%);
+        transition: transform 0.2s ease;
+        z-index: 10;
+      }
+
+      .skip-link:focus-visible {
+        transform: translateY(0);
+        outline: 3px solid #ffffff;
+        outline-offset: 3px;
+      }
+
+      .page-shell {
+        width: min(100%, 960px);
+        margin: 0 auto;
+        padding: 3rem 1.25rem 4rem;
+      }
+
+      .hero {
+        background: linear-gradient(180deg, rgba(24, 35, 61, 0.92), rgba(17, 24, 44, 0.95));
+        border: 1px solid var(--border);
+        border-radius: calc(var(--radius) + 4px);
+        padding: clamp(1.5rem, 3vw, 2.5rem);
+        box-shadow: var(--shadow);
+      }
+
+      .eyebrow {
+        margin: 0 0 0.75rem;
+        color: var(--accent);
+        font-size: 0.92rem;
+        font-weight: 700;
+        letter-spacing: 0.12em;
+        text-transform: uppercase;
+      }
+
+      h1 {
+        margin: 0;
+        font-size: clamp(2.1rem, 5vw, 3.8rem);
+        line-height: 1.02;
+        letter-spacing: -0.04em;
+      }
+
+      .intro {
+        max-width: 62ch;
+        margin: 1rem 0 0;
+        color: var(--muted);
+        font-size: 1.05rem;
+        line-height: 1.65;
+      }
+
+      .faq-list {
+        display: grid;
+        gap: 1rem;
+        margin-top: 1.5rem;
+      }
+
+      .example {
+        border: 1px solid var(--border);
+        border-radius: var(--radius);
+        background: rgba(17, 24, 44, 0.72);
+        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
+        overflow: clip;
+      }
+
+      .details {
+        padding: 0;
+      }
+
+      .details > summary {
+        list-style: none;
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        gap: 1rem;
+        padding: 1.15rem 1.25rem;
+        cursor: pointer;
+        font-size: 1.02rem;
+        font-weight: 700;
+        line-height: 1.4;
+        color: var(--text);
+      }
+
+      .details > summary::-webkit-details-marker {
+        display: none;
+      }
+
+      .details > summary::after {
+        content: "";
+        width: 0.8rem;
+        height: 0.8rem;
+        flex: 0 0 auto;
+        border-right: 2px solid var(--accent-strong);
+        border-bottom: 2px solid var(--accent-strong);
+        transform: rotate(45deg);
+        transition: transform 0.2s ease;
+      }
+
+      .details[open] > summary {
+        background: linear-gradient(180deg, rgba(143, 180, 255, 0.12), rgba(143, 180, 255, 0.04));
+        border-bottom: 1px solid rgba(167, 189, 255, 0.14);
+      }
+
+      .details[open] > summary::after {
+        transform: rotate(225deg);
+      }
+
+      .details > summary:focus-visible {
+        outline: 3px solid var(--accent);
+        outline-offset: -3px;
+      }
+
+      .details .details-body {
+        padding: 0 1.25rem 1.25rem;
+        color: var(--muted);
+        line-height: 1.7;
+      }
+
+      .details .details-body p {
+        margin: 0.9rem 0 0;
+      }
+
+      .details .details-body p:first-child {
+        margin-top: 1rem;
+      }
+
+      .details .details-body ul {
+        margin: 0.9rem 0 0;
+        padding-left: 1.25rem;
+      }
+
+      .details .details-body li + li {
+        margin-top: 0.45rem;
+      }
+
+      footer {
+        margin-top: 1.5rem;
+        color: rgba(174, 185, 214, 0.85);
+        font-size: 0.92rem;
+        text-align: center;
+      }
+
+      @media (max-width: 640px) {
+        .page-shell {
+          padding-inline: 0.85rem;
+          padding-top: 2.5rem;
+        }
+
+        .details > summary {
+          padding: 1rem 1rem;
+          font-size: 0.98rem;
+        }
+
+        .details .details-body {
+          padding-inline: 1rem;
+          padding-bottom: 1rem;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#maincontent">Skip to main content</a>
+    <main id="maincontent" class="page-shell">
+      <section class="hero" aria-labelledby="faq-title">
+        <p class="eyebrow">Cat FAQ</p>
+        <h1 id="faq-title">Everything you wanted to know about cats</h1>
+        <p class="intro">
+          A compact set of common cat questions with answers tucked into expandable disclosures.
+          Tap or press Enter on any question to open it.
+        </p>
+
+        <div class="faq-list" aria-label="Frequently asked questions about cats">
+          <article class="example">
+            <details class="details">
+              <summary>Why do cats purr?</summary>
+              <div class="details-body">
+                <p>
+                  Cats purr for several reasons: they often do it when they feel safe and content,
+                  but they may also purr to self-soothe or during recovery.
+                </p>
+              </div>
+            </details>
+          </article>
+
+          <article class="example">
+            <details class="details">
+              <summary>How much sleep do cats need?</summary>
+              <div class="details-body">
+                <p>
+                  Most cats sleep 12 to 16 hours a day, and kittens or older cats can sleep even
+                  more. Their bursts of energy tend to come in short, playful windows.
+                </p>
+              </div>
+            </details>
+          </article>
+
+          <article class="example">
+            <details class="details">
+              <summary>Why do cats knead blankets or laps?</summary>
+              <div class="details-body">
+                <p>
+                  Kneading is a comforting behavior that starts in kittenhood. Adult cats often
+                  keep doing it when they're relaxed, happy, or settling in for rest.
+                </p>
+              </div>
+            </details>
+          </article>
+
+          <article class="example">
+            <details class="details">
+              <summary>Do indoor cats need enrichment?</summary>
+              <div class="details-body">
+                <p>
+                  Yes. Cats stay healthier and happier with climbing spots, scratching surfaces,
+                  toys, and daily play that mimics hunting.
+                </p>
+                <ul>
+                  <li>Rotate toys to keep them interesting.</li>
+                  <li>Offer vertical space like shelves or cat trees.</li>
+                  <li>Use puzzle feeders for mental stimulation.</li>
+                </ul>
+              </div>
+            </details>
+          </article>
+
+          <article class="example">
+            <details class="details">
+              <summary>Why do cats bring their tails up high?</summary>
+              <div class="details-body">
+                <p>
+                  A tail held upright usually signals confidence and friendliness. It is often a
+                  cat's way of saying hello.
+                </p>
+              </div>
+            </details>
+          </article>
+        </div>
+      </section>
+
+      <footer>Built as a simple, accessible disclosure FAQ.</footer>
+    </main>
+  </body>
+</html>
*** End Patch
